from pathlib import Path

p = Path(__file__).resolve().parents[1] / 'dashboard' / 'index.html'
s = p.read_text(encoding='utf-8')

css = r''':root{font-family:"IBM Plex Sans",ui-sans-serif,system-ui,sans-serif;color:#e8edf1;background:#07090d;color-scheme:dark;--bg:#07090d;--panel:#0f141a;--panel2:#151b22;--line:#29313a;--text:#e8edf1;--muted:#8d98a3;--faint:#5e6873;--accent:#d8a928;--ok:#33c78b;--warn:#d9a441;--bad:#ef626d;--max:1240px;--mono:"IBM Plex Mono",ui-monospace,SFMono-Regular,Menlo,monospace}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-width:320px;background:var(--bg)}a{color:inherit}button{font:inherit}header{position:sticky;top:0;z-index:10;background:#07090df5;border-bottom:1px solid var(--line)}.top{max-width:var(--max);margin:auto;min-height:62px;padding:10px 16px;display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{display:flex;align-items:center;gap:10px}.mark{width:30px;height:30px;display:grid;place-items:center;border:1px solid var(--accent);border-radius:6px;color:var(--accent);font-weight:800}.brand-title{font-size:14px;font-weight:750}.brand-sub{margin-top:3px;color:var(--muted);font:10px var(--mono)}.header-meta{display:flex;align-items:center;gap:8px}.clock{display:none;color:var(--muted);font:10px var(--mono)}.status{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:5px;padding:6px 8px;color:#cbd2d8;font:700 9px var(--mono)}.dot{width:7px;height:7px;border-radius:50%;background:var(--faint)}.dot.ok{background:var(--ok)}.dot.warn{background:var(--warn)}.dot.bad{background:var(--bad)}.page-nav{max-width:var(--max);margin:auto;padding:0 16px;display:flex;gap:3px;overflow:auto;border-bottom:1px solid var(--line)}.page-nav a{color:var(--muted);text-decoration:none;padding:10px 11px;font:700 10px var(--mono);white-space:nowrap}.page-nav a:hover{color:var(--text);background:var(--panel2)}main{max-width:var(--max);margin:auto;padding:28px 16px 54px}.page{display:block;scroll-margin-top:110px;border-bottom:1px solid var(--line);padding-bottom:42px;margin-bottom:42px}.kicker{margin-bottom:10px;color:var(--accent);font:10px var(--mono);letter-spacing:.12em;text-transform:uppercase}.hero{display:block;margin-bottom:22px}.hero h1{max-width:800px;margin:0 0 12px;font-size:40px;line-height:1.02;letter-spacing:-.05em}.hero p{max-width:720px;color:var(--muted);line-height:1.62;font-size:13px;margin:0}.hero-side{margin-top:14px;color:var(--muted);font:10px/1.9 var(--mono)}.section-label{margin:25px 0 9px;color:#cbd2d8;font:10px var(--mono);letter-spacing:.1em;text-transform:uppercase}.grid,.chart-layout,.story-facts,.decision-grid,.flow{display:grid;grid-template-columns:1fr;gap:10px}.panel,.fact,.chart-panel,.story-block{background:var(--panel);border:1px solid var(--line);border-radius:7px;padding:15px}.panel.wide,.panel.full{grid-column:auto}.panel h2{margin:0 0 13px;color:#cbd2d8;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.big{margin-bottom:7px;font:700 28px var(--mono);letter-spacing:-.04em}.meta{color:var(--muted);font-size:11px;line-height:1.55}.row{display:flex;justify-content:space-between;gap:12px;border-top:1px solid var(--line);padding-top:8px;margin-top:8px;color:var(--muted);font-size:11px}.row strong{color:var(--text);font:600 11px var(--mono);text-align:right}.ok{color:var(--ok)!important}.warn{color:var(--warn)!important}.bad{color:var(--bad)!important}.accent{color:var(--accent)!important}.notice{display:flex;gap:10px;line-height:1.5;color:#d5dbe0;font-size:12px}.notice-mark{color:var(--bad)}.notice-mark.warn{color:var(--warn)}.metric small{display:block;color:var(--muted);font-size:9px;letter-spacing:.08em}.metric b{display:block;margin-top:5px;color:var(--text);font:600 14px var(--mono)}.table-wrap{overflow-x:auto}.table{width:100%;border-collapse:collapse;font-size:11px}.table th,.table td{padding:8px;border-top:1px solid var(--line);text-align:left;white-space:nowrap}.table th{color:var(--muted);font:9px var(--mono);letter-spacing:.06em;text-transform:uppercase}.table td{color:#dbe0e4}.table td.num{font-family:var(--mono);text-align:right}.table td.state{font:700 9px var(--mono)}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:17px}.action{border:1px solid var(--line);background:var(--panel2);color:var(--text);border-radius:5px;padding:9px 11px;cursor:pointer;font-size:11px;font-weight:700}.action.primary{border-color:var(--accent);color:var(--accent)}.story-intro{max-width:850px}.story-facts{margin:22px 0 10px}.fact small{display:block;color:var(--muted);font-size:9px;letter-spacing:.08em;text-transform:uppercase}.fact strong{display:block;margin-top:7px;font:600 16px var(--mono)}.story-block{margin-top:10px}.story-block h2{margin:0 0 9px;font-size:12px}.story-block p{margin:0;color:var(--muted);line-height:1.65;font-size:12px}.chart-head{display:flex;justify-content:space-between;gap:12px;margin-bottom:10px;font-size:11px}.chart-head span{color:var(--muted);font:9px var(--mono);text-align:right}.chart-panel svg{display:block;width:100%;height:auto;max-width:100%;overflow:visible}.chart-grid{stroke:var(--line)}.chart-line{fill:none;stroke:var(--accent);stroke-width:2}.chart-area{fill:var(--accent);opacity:.07}.chart-label{font:11px var(--mono);fill:var(--muted)}.chart-label.strong{fill:var(--text)}.whisker-svg{display:block;width:100%;height:auto;max-width:100%}.whisker-axis,.whisker-ci{stroke:var(--line);stroke-width:1}.whisker-point{fill:var(--warn)}.whisker-point.bad{fill:var(--bad)}.whisker-text{font:10px var(--mono);fill:var(--muted)}.whisker-value{font:10px var(--mono);fill:var(--text)}.flow-node{border:1px solid var(--line);background:var(--panel);border-radius:6px;padding:12px}.flow-node strong{display:block;font-size:11px}.flow-node span{display:block;margin-top:6px;color:var(--muted);font:9px var(--mono)}.empty{border:1px dashed var(--line);padding:15px;color:var(--muted);font-size:11px;line-height:1.6}footer{max-width:var(--max);margin:auto;padding:0 16px 28px;color:var(--muted);font-size:10px;line-height:1.8}footer .footer-line{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:13px;margin-top:8px}footer strong{color:var(--text)}footer a{color:var(--accent)}@media(min-width:768px){.clock{display:inline}.top{padding:11px 24px}.page-nav{padding:0 24px}.page-nav a{padding:11px 15px}.hero{display:flex;justify-content:space-between;gap:30px}.hero-side{min-width:210px;text-align:right;margin-top:0}.hero h1{font-size:clamp(42px,5vw,62px)}main{padding:34px 24px 70px}.grid{grid-template-columns:repeat(12,1fr);gap:12px}.panel{grid-column:span 4}.panel.wide{grid-column:span 8}.panel.full{grid-column:1/-1}.chart-layout{grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:12px}.story-facts{grid-template-columns:repeat(4,1fr);gap:12px}.decision-grid{grid-template-columns:repeat(4,1fr);gap:18px}.flow{grid-template-columns:repeat(4,1fr);gap:8px}.story-block{max-width:900px;padding:18px}.chart-panel{padding:17px}footer{padding:0 24px 34px}}'''
start=s.index('<style>')+len('<style>'); end=s.index('</style>',start)
s=s[:start]+css+s[end:]

# Continuous scroll navigation: anchors only, no page switching or hidden sections.
old_nav='<nav class="page-nav" aria-label="Research archive pages"><button data-page="story" class="active">Story</button><button data-page="terminal">Terminal</button><button data-page="visual">Visual</button></nav>'
new_nav='<nav class="page-nav" aria-label="Research archive sections"><a href="#page-story">Story</a><a href="#page-terminal">Terminal</a><a href="#page-visual">Visual</a></nav>'
s=s.replace(old_nav,new_nav)

# All sections remain visible.
s=s.replace('body data-page="story"','body')
s=s.replace('.page{display:block;scroll-margin-top:110px;', '.page{display:block;scroll-margin-top:110px;')
# Update refresh label.
s=s.replace('REFRESH · 5 MIN<br>LAST FETCH · <span id="visualFetched">—</span>', 'REFRESH · 15 MIN<br>LAST FETCH · <span id="visualFetched">—</span>')
s=s.replace('This page is a visual reading of persisted market observations.', 'This section is a visual reading of persisted market observations.')

# Replace unlabeled market SVG with labeled SVG elements.
old_svg='<svg id="marketChart" viewBox="0 0 900 260" role="img" aria-label="BTCUSDT recent close observations"><line class="chart-grid" x1="0" y1="30" x2="900" y2="30"/><line class="chart-grid" x1="0" y1="130" x2="900" y2="130"/><line class="chart-grid" x1="0" y1="230" x2="900" y2="230"/><path id="chartArea" class="chart-area"/><path id="chartLine" class="chart-line"/></svg>'
new_svg='<svg id="marketChart" viewBox="0 0 900 300" width="100%" height="auto" preserveAspectRatio="xMidYMid meet" role="img" aria-label="BTCUSDT recent close observations"><line class="chart-grid" x1="70" y1="30" x2="880" y2="30"/><line class="chart-grid" x1="70" y1="130" x2="880" y2="130"/><line class="chart-grid" x1="70" y1="230" x2="880" y2="230"/><text id="chartMax" class="chart-label strong" x="4" y="34">MAX —</text><text id="chartMid" class="chart-label" x="4" y="134">—</text><text id="chartMin" class="chart-label strong" x="4" y="234">MIN —</text><text id="chartFirst" class="chart-label" x="70" y="278">—</text><text id="chartLast" class="chart-label" x="880" y="278" text-anchor="end">—</text><path id="chartArea" class="chart-area"/><path id="chartLine" class="chart-line"/></svg>'
s=s.replace(old_svg,new_svg)

# Add whisker section and replace unsupported empty-only visual.
needle='<div class="section-label">Views not rendered without evidence</div><section class="empty">Confidence-interval charts, experiment timelines, and lifecycle maps are not drawn from imagination. When a persisted backend record is not available for a view, this page keeps the gap visible.</section>'
whisker='''<div class="section-label">Research EV and CI95</div><section class="chart-panel"><div class="chart-head"><strong>Point estimate with 95% confidence interval</strong><span>Backend results only · unavailable is explicit</span></div><svg id="whiskerChart" class="whisker-svg" viewBox="0 0 900 250" width="100%" height="auto" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Research expected value confidence interval chart"><line class="whisker-axis" x1="250" y1="20" x2="880" y2="20"/><line class="whisker-axis" x1="250" y1="20" x2="250" y2="225"/><line class="whisker-axis" x1="565" y1="20" x2="565" y2="225"/><text class="whisker-text" x="250" y="242">CI / EV scale</text><text class="whisker-text" x="565" y="242">0 bps</text><g id="whiskerRows"><text class="whisker-text" x="10" y="55">H-FB1</text><text class="whisker-value" x="250" y="55">UNAVAILABLE</text><text class="whisker-text" x="10" y="95">H-SW1 overall</text><text class="whisker-value" x="250" y="95">UNAVAILABLE</text><text class="whisker-text" x="10" y="135">H-SW1 independent</text><text class="whisker-value" x="250" y="135">UNAVAILABLE</text><text class="whisker-text" x="10" y="175">H-SW1 quarter</text><text class="whisker-value" x="250" y="175">UNAVAILABLE</text></g></svg></section><div class="section-label">Evidence path</div><div class="flow"><div class="flow-node"><strong>Binance public API</strong><span>MARKET SOURCE</span></div><div class="flow-node"><strong>Collector runtime</strong><span>CAPTURE LAYER · HOST NOT CLAIMED</span></div><div class="flow-node"><strong>Supabase</strong><span>PERSISTED EVIDENCE</span></div><div class="flow-node"><strong>Dashboard</strong><span>READ-ONLY SURFACE</span></div></div>'''
s=s.replace(needle,whisker)

# Remove duplicate old evidence path before the new one.
old_flow='<div class="section-label">Evidence path</div><div class="flow"><div class="flow-node"><strong>Market source</strong><span id="flowMarket">PUBLIC DATA</span></div><div class="flow-node"><strong>API</strong><span id="flowApi">READING</span></div><div class="flow-node"><strong>Research store</strong><span id="flowStore">READING</span></div><div class="flow-node"><strong>Archive</strong><span id="flowArchive">READING</span></div></div>'
s=s.replace(old_flow,'')

# Replace runtime only in controlled fragments while preserving fetch functions.
s=s.replace("let activePage='story',timer=null;", "let terminalTimer=null,slowTimer=null,researchPayloads={hfb:null,sw1Ref:null,sw1Ind:null};")
s=s.replace("function setPage(page){activePage=['story','terminal','visual'].includes(page)?page:'story';document.body.dataset.page=activePage;document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+activePage));document.querySelectorAll('.page-nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===activePage));loadPage();clearInterval(timer);timer=setInterval(loadPage,activePage==='terminal'?15000:300000)}", "function setPage(){return} ")
s=s.replace("if($(prefix+'Win'))$(prefix+'Win').textContent=x.win_rate==null?'UNAVAILABLE':fmt(Number(x.win_rate)*100,2)+'%'", "if($(prefix+'Win'))$(prefix+'Win').textContent=x.win_rate==null?'UNAVAILABLE':fmt(Number(x.win_rate)*100,2)+'%';")
# Add chart labels to renderChart.
needle2="$('chartLine').setAttribute('d','M '+pts.join(' L '));$('chartArea').setAttribute('d','M '+pts.join(' L ')+' L 900,230 L 0,230 Z');"
rep2="$('chartLine').setAttribute('d','M '+pts.map((p,i)=>{const [x,y]=p.split(',');return (i?'L ':'M ')+(Number(x)+70)+','+y}).join(' '));$('chartArea').setAttribute('d','M '+pts.map((p,i)=>{const [x,y]=p.split(',');return (i?'L ':'M ')+(Number(x)+70)+','+y}).join(' ')+' L 880,230 L 70,230 Z');$('chartMax').textContent='MAX '+fmt(max,2);$('chartMid').textContent=fmt((max+min)/2,2);$('chartMin').textContent='MIN '+fmt(min,2);$('chartFirst').textContent=iso(data[0].open_time_ms);$('chartLast').textContent=iso(data.at(-1).open_time_ms);"
s=s.replace(needle2,rep2)
# Record HFB payload in terminal.
s=s.replace("setHeader(h);$('terminalHealth')", "researchPayloads.hfb=r;setHeader(h);$('terminalHealth')")
# Extend loadFrozen with whisker renderer before status.
s=s.replace("renderResult('sw1Ref',a);renderResult('sw1Ind',b);st.textContent='Comparison complete · read-only · no execution'", "researchPayloads.sw1Ref=a;researchPayloads.sw1Ind=b;renderResult('sw1Ref',a);renderResult('sw1Ind',b);renderWhiskers();st.textContent='Comparison complete · read-only · no execution'")
# Replace bottom runtime bootstrap.
old_boot="function loadPage(){if(activePage==='story')return loadStory();if(activePage==='terminal')return loadTerminal();return loadVisual()}document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));$('runSw1').addEventListener('click',loadFrozen);setPage('story');setInterval(updateClock,1000);updateClock();"
new_boot="function whiskerPoint(y,label,payload,cls){const x=resultRow(payload),value=x?.mean_net_bps,lo=x?.net_ci95_low,hi=x?.net_ci95_high;if(value==null||lo==null||hi==null)return `<text class=\\\"whisker-text\\\" x=\\\"10\\\" y=\\\"${y}\\\">${label}</text><text class=\\\"whisker-value\\\" x=\\\"250\\\" y=\\\"${y}\\\">UNAVAILABLE</text>`;const scale=v=>565+Number(v)*8;return `<text class=\\\"whisker-text\\\" x=\\\"10\\\" y=\\\"${y}\\\">${label}</text><line class=\\\"whisker-ci ${cls||''}\\\" x1=\\\"${scale(lo)}\\\" y1=\\\"${y-4}\\\" x2=\\\"${scale(hi)}\\\" y2=\\\"${y-4}\\\"/><circle class=\\\"whisker-point ${cls||''}\\\" cx=\\\"${scale(value)}\\\" cy=\\\"${y-4}\\\" r=\\\"5\\\"/><text class=\\\"whisker-value\\\" x=\\\"${Math.min(scale(hi)+8,820)}\\\" y=\\\"${y}\\\">${fmt(value)} bps · ${fmt(lo)}→${fmt(hi)}</text>`}function renderWhiskers(){if(!$('whiskerRows'))return;$('whiskerRows').innerHTML=whiskerPoint(55,'H-FB1',researchPayloads.hfb,'bad')+whiskerPoint(95,'H-SW1 overall',researchPayloads.sw1Ref,'warn')+whiskerPoint(135,'H-SW1 independent',researchPayloads.sw1Ind,'warn')+`<text class=\\\"whisker-text\\\" x=\\\"10\\\" y=\\\"175\\\">H-SW1 quarter</text><text class=\\\"whisker-value\\\" x=\\\"250\\\" y=\\\"175\\\">SEE TERMINAL BREAKDOWN</text>`}function loadPage(){loadStory();loadTerminal();loadVisual()}$('runSw1').addEventListener('click',loadFrozen);loadPage();terminalTimer=setInterval(loadTerminal,15000);slowTimer=setInterval(()=>{loadStory();loadVisual();loadFrozen()},900000);setInterval(updateClock,1000);updateClock();"
if old_boot not in s: raise SystemExit('bootstrap not found')
s=s.replace(old_boot,new_boot)

p.write_text(s,encoding='utf-8')
print('M10 continuous scroll implementation applied')
